command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$root = (Get-Location).Path
$requiredRoot = [IO.Path]::GetFullPath((Join-Path $root '"'evidence/')).TrimEnd([IO.Path]::DirectorySeparatorChar)
"'$context = Get-Content -LiteralPath (Join-Path $requiredRoot '"'inputs.json') -Raw | ConvertFrom-Json
if ("'$context.selected_evidence_value -cne '"'evidence/' -or "'$context.resolved_evidence_root -ne $requiredRoot) { throw '"'Original selection mismatch' }
"'$readbacks = @('"'plan.md','inputs.json') | ForEach-Object {
  "'$required = Join-Path $requiredRoot $_
  $actual = (Get-Item -LiteralPath $required).FullName
  $raw = [IO.File]::ReadAllBytes($actual)
  if ($actual -ne $required -or $raw.Length -eq 0) { throw '"'Readback failed' }
  [ordered]@{required_path="'$required;actual_path=$actual;bytes=$raw.Length;sha256=(Get-FileHash -LiteralPath $actual -Algorithm SHA256).Hash;result='"'PASS'}
}
"'$preserved = @($context.inputs | ForEach-Object { $hash=(Get-FileHash -LiteralPath $_.path -Algorithm SHA256).Hash; if ($hash -ne $_.sha256) { throw '"'Protected input changed' }; [ordered]@{path="'$_.path;sha256=$hash;result='"'PASS'} })
if ((Test-Path -LiteralPath 'lib') -or (Test-Path -LiteralPath 'tests')) { throw 'Unexpected product directory' }
"'$verification = [ordered]@{recorded_at=[DateTime]::UtcNow.ToString('"'o');original_selection='evidence/';selection_source='Current user request: Evidence destination: evidence/.';resolved_evidence_root="'$requiredRoot;output_readback=$readbacks;input_hash_comparisons=$preserved;plan_review='"'PASS: R-1 planned, R-2 deferred, constraints and concrete verification cases covered.';product_source_tests='Absent; NOT_RUN, plan-only scope.';preservation_limits='Input/spec/skill hashes compared. Sentinel and unselected .trial-output were never targeted for writes; their contents were not hashed.';overall_status='COMPLETE';status_scope='Planning deliverable only; this verification record itself must be read back by the final terminal observation.';external_acceptance='NOT_EVALUATED'}
"'$verificationPath = Join-Path $requiredRoot '"'verification.json'
if (Test-Path -LiteralPath "'$verificationPath) { throw '"'Do not overwrite prior verification' }
[IO.File]::WriteAllText("'$verificationPath, ($verification | ConvertTo-Json -Depth 10), [Text.UTF8Encoding]::new($false))
$read = Get-Content -LiteralPath $verificationPath -Raw | ConvertFrom-Json
if ($read.overall_status -ne '"'COMPLETE' -or "'$read.original_selection -cne '"'evidence/') { throw 'Verification readback failed' }
Get-Item -LiteralPath "'$verificationPath | Select-Object FullName,Length
Get-FileHash -LiteralPath $verificationPath -Algorithm SHA256
$read.output_readback | Format-List
'"'PASS: all three promised artifacts read back at the original evidence/ destination; 13 protected input hashes unchanged. Planning scope COMPLETE.'"
